import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
for q in ['preterm piglet inotrope cardiac output cerebral blood flow','premature piglets dobutamine dopamine cerebral blood flow','piglet dobutamine cerebral perfusion preterm']:
 r=requests.get(u,params={'db':'pubmed','term':q,'retmode':'json','retmax':20},timeout=20)
 print('\nQUERY',q,'STATUS',r.status_code)
 ids=r.json()['esearchresult']['idlist']
 if ids:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids: print(i,x[i].get('title'),x[i].get('pubdate'))
 else: print('No hits')
